{"code": "import os
from PIL import Image

# Check if we can identify which files are corrupted
images_path = 'data_small/images/Images/'
corrupted_files = []

# Walk through the directory and check each image
for root, dirs, files in os.walk(images_path):
    for file in files:
        if file.lower().endswith(('.jpg', '.jpeg', '.png')):
            file_path = os.path.join(root, file)
            try:
                with Image.open(file_path) as img:
                    img.verify()
            except Exception as e:
                corrupted_files.append(file_path)
                print(f"Corrupted file: {file_path} - Error: {e}")

print(f"\nTotal corrupted files: {len(corrupted_files)}")"}

